<?php require_once __DIR__.'/config/db.php';$page_title='Your Bag — MediNova';$items=cart_products($pdo);$total=cart_total($pdo);require __DIR__.'/includes/store_header.php';?><section class="page-hero" style="min-height:35vh"><p class="kicker">YOUR SHOPPING BAG</p><h1>Your <span>essentials.</span></h1></section><section class="content-section"><div class="cart-layout"><div class="cart-box"><?php if(!$items):?><div class="empty-state">Your bag is empty.<br><a class="text-link" href="shop.php">Browse the pharmacy →</a></div><?php else:foreach($items as $p):?><div class="cart-product"><div class="mini-art"><?php if($p['image']):?><img src="<?=BASE_URL?><?=e($p['image'])?>" alt="<?=e($p['name'])?>"><?php else:?><div class="medicine-art"><i class="pill"></i></div><?php endif;?></div><div><h3><?=e($p['name'])?></h3><p>Rs. <?=number_format((float)$p['price'])?> × <?=$p['qty']?></p></div><div class="qty"><a href="cart_action.php?action=remove&product_id=<?=$p['id']?>">×</a></div></div><?php endforeach;endif;?></div><aside class="summary-box"><p class="kicker">ORDER SUMMARY</p><div class="order-summary"><div><span>Items</span><span><?=cart_count()?></span></div><div class="grand"><span>Total</span><strong>Rs. <?=number_format($total)?></strong></div></div><?php if($items):?><a class="btn btn-light" style="width:100%;margin-top:20px" href="checkout.php">Checkout ↗</a><?php endif;?></aside></div></section><?php require __DIR__.'/includes/store_footer.php'; ?>
